-- Disposable local database fixtures. No SMTP, token, mailbox or real submission.
begin;
do $$
declare actor uuid;owner_email text;opp uuid;p public.propostas;claim jsonb;sid uuid;r jsonb;nonce text;blocked boolean;
 body text:='Olá, Leo. Esta é uma mensagem controlada para validar a comunicação do Sistema de Eventos. Não constitui proposta comercial, reserva, cobrança ou confirmação de evento. Para validar o retorno, responda a este mesmo e-mail com: TESTE RECEBIDO QA-COM-EMAIL-01. Não encaminhe dados pessoais ou documentos neste teste.';
 subject text:='[TESTE EVENTOS] QA-COM-EMAIL-01 — sem valor comercial';
 mid text:='<'||gen_random_uuid()||'@embaixadacarioca.com.br>';mime text:=repeat('a',64);response text:=repeat('b',64);
 before_proposal jsonb;before_flags jsonb;binding jsonb;attempt uuid:=gen_random_uuid();case_result jsonb;before_leads bigint;before_cases bigint;
begin
 assert (select relrowsecurity from pg_class where oid='event_private.smtp_pilot_receipts'::regclass),'private receipt RLS';
 assert not has_table_privilege('service_role','event_private.smtp_pilot_receipts','select'),'no raw worker table grant';
 assert not has_function_privilege('authenticated','public.event_smtp_pilot_prepare(uuid,uuid,integer,text,text,timestamptz,timestamptz)','execute'),'no client reservation';
 assert not has_function_privilege('anon','public.event_smtp_pilot_status(uuid,text)','execute'),'no anonymous readback';
 assert not exists(select 1 from event_private.smtp_pilot_receipts),'migration installs empty';
 assert encode(sha256(convert_to(body,'UTF8')),'hex')='3cb5fe4c494dbfc1153166d1f20d762c2b3d784eabdd6a5d53808616d1267099','exact authorized neutral body';
 for actor,owner_email in select id,email from auth.users order by email loop
  perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'email',owner_email,'role','authenticated')::text,true);
  exit when public.is_super_admin();
 end loop;
 assert public.is_super_admin(),'fixture discovers existing Master contract';
 update auth.users set email_confirmed_at=clock_timestamp() where id=actor;
 update event_private.proposal_approval_policy set enabled=false where id;
 update event_private.mailbox_sync_state set enabled=false,capture_send_ids='{}',capture_started_at=null,capture_expires_at=null,account_id='123456789',mailbox='eventos@embaixadacarioca.com.br',activated_at_ms=floor(extract(epoch from clock_timestamp())*1000)::bigint-60000,watermark_ms=floor(extract(epoch from clock_timestamp())*1000)::bigint-60000 where singleton;
 update event_private.channel_credentials set enabled=false,expected_account='eventos@embaixadacarioca.com.br' where provider='mailbox';
 assert not exists(select 1 from event_private.mailbox_oauth_connection),'fixture requires no previous connection';
 insert into event_private.mailbox_oauth_attempts(id,owner_id,state,client_fingerprint,prepare_expires_at)values(attempt,actor,'stored',repeat('c',64),clock_timestamp()+interval '5 minutes');
 insert into event_private.mailbox_oauth_connection(singleton,attempt_id,owner_id,account_id,mailbox,vault_secret_id,client_fingerprint)values(true,attempt,actor,'123456789','eventos@embaixadacarioca.com.br',gen_random_uuid(),repeat('c',64));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'email',owner_email,'role','authenticated')::text,true);
 select count(*) into before_leads from public.solicitacoes_cotacao;
 select count(*) into before_cases from public.propostas;
 case_result:=public.event_neutral_email_pilot('status');
 assert case_result->>'state'='absent' and case_result->'captureActive'='false'::jsonb,'status observes absence and OFF';
 assert (select count(*)=before_cases from public.propostas),'status creates no proposal';
 case_result:=public.event_neutral_email_pilot('prepare');
 assert case_result->>'state'='ready' and case_result->'approvalRequired'='false'::jsonb,'supported owner preparation';
 assert not (case_result?'sendId'),'ready response omits absent optional send identifier';
 select * into p from public.propostas where id=(case_result->>'proposalId')::uuid;opp:=p.oportunidade_id;
 assert p.revision=1 and p.total=0 and p.cliente_email=owner_email,'zero-value exact owner case';
 assert (select count(*)=before_cases+1 from public.propostas),'one tagged proposal';
 assert (select count(*)=before_leads from public.solicitacoes_cotacao),'no public lead or lead notification';
 assert not exists(select 1 from public.event_outbox where proposal_id=p.id),'preparation does not send';
 assert public.event_neutral_email_pilot('prepare')=case_result,'prepare is idempotent without reset';
 assert (select count(*)=before_cases+1 from public.propostas),'no duplicate case';
 claim:=public.begin_event_send_reviewed(p.id,p.revision,'email',owner_email,body,subject,null);
 assert (claim->>'claimed')::boolean,'real reviewed-send contract admits neutral fixture';sid:=(claim#>>'{send,id}')::uuid;
 select to_jsonb(q) into before_proposal from public.propostas q where id=p.id;
 select to_jsonb(s) into before_flags from event_private.mailbox_sync_state s where singleton;
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'authenticated claim cannot finalize transport';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,gen_random_uuid(),1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'wrong owner blocked';
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,2,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'second attempt blocked';
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '59 seconds');exception when others then blocked:=true;end;assert blocked,'short gate blocked';
 update auth.users set email_confirmed_at=null where id=actor;
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'revoked Master blocked';
 update auth.users set email_confirmed_at=clock_timestamp() where id=actor;
 update event_private.mailbox_sync_state set enabled=true where singleton;
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'capture must remain OFF';
 update event_private.mailbox_sync_state set enabled=false where singleton;
 r:=public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');nonce:=r->>'claim_token';
 assert r->>'state'='prepared' and length(nonce)=64,'durable private reservation';
 assert (select deadline=prepared_at+interval '45 seconds' from event_private.smtp_pilot_receipts where send_id=sid),'one clock instant pins exact reservation deadline';
 blocked:=false;begin perform public.event_smtp_pilot_prepare(sid,actor,1,mid,mime,clock_timestamp()-interval '1 second',clock_timestamp()+interval '2 minutes');exception when others then blocked:=true;end;assert blocked,'reservation never resets or repeats';
 blocked:=false;begin perform public.event_smtp_pilot_start(sid,repeat('0',64));exception when others then blocked:=true;end;assert blocked,'wrong claim token blocked';
 r:=public.event_smtp_pilot_start(sid,nonce);assert r->>'state'='sending' and r->>'deadline' is not null and r->>'gate_expires_at' is not null,'start returns bounded deadline';
 blocked:=false;begin perform public.event_smtp_pilot_start(sid,nonce);exception when others then blocked:=true;end;assert blocked,'start cannot replay';
 blocked:=false;begin perform public.event_smtp_pilot_finish(sid,nonce,'DATA_250',repeat('d',64),mid,response,clock_timestamp());exception when others then blocked:=true;end;assert blocked,'MIME drift blocked';
 insert into event_private.mailbox_outbound_headers(account_id,outbound_message_id,send_id,send_attempt,proposal_revision,evidence_sha256)values('123456789',mid,sid,1,1,repeat('e',64));
 blocked:=false;begin perform public.event_smtp_pilot_finish(sid,nonce,'DATA_250',mime,mid,response,clock_timestamp());exception when others then blocked:=true;end;assert blocked,'conflicting mapping cannot be overwritten';
 assert (select status='sending' from event_outbox where id=sid),'failed mapping rolls acceptance back';
 assert (select state='sending' from event_private.smtp_pilot_receipts where send_id=sid),'receipt is not partially committed';
 assert not exists(select 1 from event_messages where external_id='send:'||sid::text),'no partial timeline';
 delete from event_private.mailbox_outbound_headers where account_id='123456789' and outbound_message_id=mid and evidence_sha256=repeat('e',64);
 r:=public.event_smtp_pilot_finish(sid,nonce,'DATA_250',mime,mid,response,clock_timestamp());assert r->>'state'='accepted','typed SMTP acceptance';
 assert (select provider_id is null and status='accepted' from public.event_outbox where id=sid),'no invented HTTP provider ID';
 assert (select count(*)=1 from event_private.mailbox_outbound_headers where send_id=sid and outbound_message_id=mid and send_attempt=1 and proposal_revision=1),'one exact private binding';
 assert (select count(*)=1 from public.event_messages where external_id='send:'||sid::text and channel='email' and proposal_revision=1),'one outbound timeline record';
 assert (select to_jsonb(q)=before_proposal from public.propostas q where id=p.id),'neutral pilot creates no commercial deadlines/state effects';
 assert (select to_jsonb(s)=before_flags from event_private.mailbox_sync_state s where singleton),'SMTP does not activate capture/cursor';
 r:=public.event_smtp_pilot_finish(sid,nonce,'DATA_250',mime,mid,response,clock_timestamp());assert r->>'state'='accepted','committed response readback is idempotent';
 assert (select count(*)=1 from public.event_messages where external_id='send:'||sid::text),'no duplicate timeline';
 blocked:=false;begin perform public.event_smtp_pilot_finish(sid,nonce,'UNCERTAIN',mime,mid,null,clock_timestamp());exception when others then blocked:=true;end;assert blocked,'late uncertainty cannot erase accepted proof';

 assert not has_table_privilege('authenticated','event_private.neutral_reply_reviews','select'),'no direct client audit read';
 assert not has_table_privilege('service_role','event_private.neutral_reply_reviews','insert'),'no raw worker writes';
 assert not has_function_privilege('anon','public.event_neutral_reply_begin(uuid,text,text,text,boolean)','execute'),'no anon operator';
 assert not has_function_privilege('authenticated','public.event_neutral_reply_store_preview(uuid,uuid,jsonb)','execute'),'browser cannot fabricate provider content';
 assert not has_function_privilege('service_role','public.event_neutral_reply_commit(uuid,text,boolean)','execute'),'worker cannot confirm for owner';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'email',owner_email,'role','authenticated')::text,true);
 blocked:=false;begin perform public.event_neutral_reply_begin(sid,'<delivered@provider.test>','<reply@client.test>',repeat('f',64),false);exception when others then blocked:=true;end;assert blocked,'explicit provider review required';
 case_result:=public.event_neutral_reply_begin(sid,'<delivered@provider.test>','<reply@client.test>',repeat('f',64),true);attempt:=(case_result->>'reviewId')::uuid;
 blocked:=false;begin perform public.event_neutral_reply_worker_context(attempt,actor);exception when others then blocked:=true;end;assert blocked,'client cannot run worker context';
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 blocked:=false;begin perform public.event_neutral_reply_worker_context(attempt,gen_random_uuid());exception when others then blocked:=true;end;assert blocked,'worker actor must match owner-created review';
 r:=public.event_neutral_reply_worker_context(attempt,actor);assert r->'ownerVerified'='true'::jsonb and r->'captureDisabled'='true'::jsonb,'trusted server context';
 binding:=jsonb_build_object('state','prepared','provenance','owner_reviewed_provider_headers','accountId',r->>'accountId','sendId',sid,'proposalId',p.id,'revision',1,'attempt',1,'providerId','1700000000000000001','folderId','1700000000000000002','inboundMessageId','<reply@client.test>','deliveredMessageId','<delivered@provider.test>','sender',owner_email,'body','Resposta sintética de teste','receivedAt',floor(extract(epoch from clock_timestamp())*1000)::bigint,'contentRead',true,'messageSent',false,'captureActivated',false,'persisted',false);
 blocked:=false;begin perform public.event_neutral_reply_store_preview(attempt,actor,binding||'{"accountId":"999"}'::jsonb);exception when others then blocked:=true;end;assert blocked,'wrong mailbox account rejected';
 blocked:=false;begin perform public.event_neutral_reply_store_preview(attempt,actor,binding||'{"inboundMessageId":"<unrelated@client.test>"}'::jsonb);exception when others then blocked:=true;end;assert blocked,'unrelated reply rejected';
 blocked:=false;begin perform public.event_neutral_reply_store_preview(attempt,actor,binding||jsonb_build_object('body',repeat('x',6001)));exception when others then blocked:=true;end;assert blocked,'oversized body rejected';
 r:=public.event_neutral_reply_store_preview(attempt,actor,binding);nonce:=r->>'previewSha256';
 assert r->>'state'='prepared' and r->'captureActive'='false'::jsonb,'private server preview with gates OFF';
 assert public.event_neutral_reply_store_preview(attempt,actor,binding)=r,'same preview idempotent';
 blocked:=false;begin perform public.event_neutral_reply_store_preview(attempt,actor,binding||'{"body":"different"}'::jsonb);exception when others then blocked:=true;end;assert blocked,'changed preview cannot overwrite original';
 blocked:=false;begin perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=true;end;assert blocked,'worker cannot confirm as owner';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'email',owner_email,'role','authenticated')::text,true);
 blocked:=false;begin perform public.event_neutral_reply_commit(attempt,nonce,false);exception when others then blocked:=true;end;assert blocked,'owner confirmation required';
 blocked:=false;begin perform public.event_neutral_reply_commit(attempt,repeat('0',64),true);exception when others then blocked:=true;end;assert blocked,'reviewed digest exact';
 blocked:=false;begin update public.propostas set snapshot=snapshot||'{"changed":true}'::jsonb where id=p.id;perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='neutral_reply_context_changed';end;assert blocked,'proposal drift rolls back';
 blocked:=false;begin update event_private.mailbox_sync_state set enabled=true where singleton;perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='oauth_capture_must_be_off';end;assert blocked,'gate drift rolls back';
 blocked:=false;begin update event_private.neutral_reply_reviews set created_at=now()-interval '6 minutes',expires_at=now()-interval '1 minute' where id=attempt;perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='neutral_reply_review_expired';end;assert blocked,'expired preview not committed';
 blocked:=false;begin
 execute 'create function pg_temp.reject_neutral_insert() returns trigger language plpgsql as ''begin raise exception ''''fixture_neutral_insert_fail'''';end;''';
 execute 'create trigger reject_neutral_insert before insert on public.event_messages for each row execute function pg_temp.reject_neutral_insert()';
 perform public.event_neutral_reply_commit(attempt,nonce,true);
 exception when others then blocked:=sqlerrm='fixture_neutral_insert_fail';end;assert blocked,'injected timeline failure reached and rolled back';
 assert (select state='prepared' and message_id is null from event_private.neutral_reply_reviews where id=attempt),'no partial audit commit';
 assert not exists(select 1 from public.event_messages where proposal_id=p.id and direction='inbound'),'no partial incoming history';
 blocked:=false;begin insert into event_private.mailbox_bound_receipts(account_id,provider_id,state,reason,inbound_message_id)values('123456789','1700000000000000001','review_required','unmatched_thread','<another@client.test>');perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='neutral_reply_already_observed';end;assert blocked,'previous provider observation is not overwritten';
 blocked:=false;begin insert into event_private.mailbox_bound_receipts(account_id,provider_id,state,reason,inbound_message_id)values('123456789','1700000000000000999','review_required','unmatched_thread','<reply@client.test>');perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='neutral_reply_already_observed';end;assert blocked,'same RFC reply under another provider ID cannot duplicate';
 blocked:=false;begin insert into event_private.mailbox_seen(account_id,provider_id,received_at_ms)values('123456789','1700000000000000001',floor(extract(epoch from clock_timestamp())*1000)::bigint);perform public.event_neutral_reply_commit(attempt,nonce,true);exception when others then blocked:=sqlerrm='neutral_reply_already_observed';end;assert blocked,'legacy seen entry is not overwritten';
 assert (select to_jsonb(q)=before_proposal from public.propostas q where id=p.id),'proposal unchanged';
 assert (select to_jsonb(s)=before_flags from event_private.mailbox_sync_state s where singleton),'flags unchanged';
 case_result:=public.event_neutral_reply_begin(sid,'<delivered@provider.test>','<reply@client.test>',repeat('f',64),true);attempt:=(case_result->>'reviewId')::uuid;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.event_neutral_reply_store_preview(attempt,actor,binding);
 raise notice 'PASS owner/worker privilege boundaries, exact immutable preview, unrelated/account/body rejection, drift/expiry and atomic failure';
end $$;
commit;
